#include "common.hpp"
using namespace fsizes;
HANDLE launch(const std::wstring& path){auto cmd=L"\""+path+L"\"";STARTUPINFOW si{sizeof(si)};PROCESS_INFORMATION pi{};if(!CreateProcessW(path.c_str(),cmd.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,nullptr,&si,&pi))return nullptr;CloseHandle(pi.hThread);return pi.hProcess;}
int wmain(){SetEnvironmentVariableW(L"FOLDERSIZE_TEST",L"1");DWORD before=0,after=0;GetWindowThreadProcessId(GetShellWindow(),&before);auto broker=launch(directory()+L"\\bin\\WindowsFolderSize.exe");if(!broker)return 2;bool ready=false;for(int i=0;i<100;i++){if(WaitNamedPipeW(sessionPipe().c_str(),100)){ready=true;break;}Sleep(50);}if(!ready)return 3;Sleep(300);auto helper=launch(directory()+L"\\bin\\WindowsFolderSizeStop.exe");if(!helper)return 4;WaitForSingleObject(helper,10000);DWORD exit=99;GetExitCodeProcess(helper,&exit);CloseHandle(helper);bool stopped=WaitForSingleObject(broker,1000)==WAIT_OBJECT_0;GetWindowThreadProcessId(GetShellWindow(),&after);CloseHandle(broker);printf("Broker-only installer stop: helper_exit=%lu stopped=%d shell_pid_unchanged=%d\n",exit,stopped,before==after);return !exit&&stopped&&before==after?0:5;}
